<?php
/** Configuration, live reachability and received-data health are distinct facts. */
class IntegrationHealth {
    private $store,$http;
    public function __construct($store,$http=null){$this->store=$store;$this->http=$http?:[self::class,'get'];}
    public static function profile($project){$platform=$project['settings']['platform_type']??'wordpress';if(!in_array($platform,['wordpress','tiam','custom'],true))$platform='custom';return ['platform'=>$platform,'inventory_authority'=>$platform==='tiam'?'tiam':($platform==='wordpress'?'wordpress':'project_inventory'),'authorities'=>['inventory'=>$platform==='tiam'?'ERP SQL/agent or its approved manual file':($platform==='wordpress'?'WooCommerce or its approved manual file':'explicit project inventory'),'sales'=>'one selected source per store','seo'=>'website metadata and Google/Composio','images'=>'existing library and website observations'],'inventory_methods'=>['automatic','manual'],'sales_methods'=>['automatic','manual'],'website_enrichment'=>['images','seo','description','size_chart'],'note'=>$platform==='tiam'?'موجودی و قیمت از تیام/فایل ERP؛ دادهٔ وب‌سایت فقط تکمیل‌کننده است.':'ووکامرس یا فایل همان منبع؛ اطلاعات هر فروشگاه و ارز جدا نگه داشته می‌شود.'];}
    public static function get($url,$headers=[]){$p=is_string($url)?parse_url($url):false;if(!$p||($p['scheme']??'')!=='https'||empty($p['host'])||isset($p['user'])||isset($p['pass'])||($p['port']??443)!==443)throw new RuntimeException('مقصد باید HTTPS عمومی باشد.');$ips=gethostbynamel($p['host'])?:[];if(!$ips)throw new RuntimeException('DNS مقصد پاسخ نداد.');foreach($ips as $ip)if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))throw new RuntimeException('مقصد خصوصی مجاز نیست.');$body='';$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_HTTPHEADER=>array_merge(['Accept: application/json'],$headers),CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15,CURLOPT_RESOLVE=>[$p['host'].':443:'.$ips[0]],CURLOPT_WRITEFUNCTION=>static function($c,$part)use(&$body){if(strlen($body)+strlen($part)>1048576)return 0;$body.=$part;return strlen($part);}]);$ok=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($ok===false)throw new RuntimeException('ارتباط قطع شد یا از مهلت تست گذشت.');$data=json_decode($body,true);return ['status'=>$status,'body'=>is_array($data)?$data:[]];}
    private static function fingerprint($project,$platform){
        $cfg=$platform==='wordpress'?($project['settings']['wordpress']??[]):($project['settings']['connections'][$platform]??[]);
        return hash('sha256',json_encode($cfg));
    }
    public function probe($project,$principal,$platform){AiAccess::write();$start=microtime(true);$result=['platform'=>$platform,'checked_at'=>time(),'success'=>false,'stages'=>[]];
        try{
            if($platform==='wordpress'){AiAccess::need('wp_crm','use');$cfg=$project['settings']['wordpress']??[];if(empty($cfg['site_url'])||empty($cfg['token']))throw new RuntimeException('آدرس وردپرس و توکن خواندن REST لازم است.');$r=call_user_func($this->http,rtrim($cfg['site_url'],'/').'/wp-json/maarksho-crm/v1/test',['X-Maarksho-Token: '.$cfg['token']]);if($r['status']!==200||($r['body']['status']??'')!=='success')throw new RuntimeException('WordPress HTTP '.(int)$r['status'].'؛ افزونه و توکن را بررسی کنید.');$result['stages'][]=['stage'=>'wordpress_auth','success'=>true];$result['capabilities']=$r['body']['capabilities']??[];}
            elseif(in_array($platform,['telegram','instagram'],true)){AiAccess::need('settings','use');$cfg=$project['settings']['connections'][$platform]??[];if(AiSocial::route($project['settings'],$platform))throw new RuntimeException('روش ChatGPT: تست سمت ابزار متصل انجام و رسید واقعی برگردانده شود؛ این روش توکن بومی شبکه را تست نمی‌کند.');$token=$cfg['access_token']??$cfg['token']??'';if(!is_string($token)||$token==='')throw new RuntimeException('توکن اتصال تنظیم نشده است.');if($platform==='telegram'){if(!preg_match('/^[0-9]+:[A-Za-z0-9_-]+$/D',$token))throw new RuntimeException('ساختار توکن تلگرام معتبر نیست.');$r=call_user_func($this->http,'https://api.telegram.org/bot'.$token.'/getMe');if($r['status']!==200||empty($r['body']['ok']))throw new RuntimeException('توکن تلگرام تأیید نشد.');$result['stages'][]=['stage'=>'bot_auth','success'=>true];$chat=$cfg['chatId']??'';if($chat==='')throw new RuntimeException('بات معتبر است؛ مقصد تلگرام تنظیم نشده.');$r=call_user_func($this->http,'https://api.telegram.org/bot'.$token.'/getChat?'.http_build_query(['chat_id'=>$chat]));if($r['status']!==200||empty($r['body']['ok']))throw new RuntimeException('دسترسی خواندن مقصد تلگرام تأیید نشد.');$result['stages'][]=['stage'=>'destination_read','success'=>true];}
                else{$id=$cfg['instagram_account_id']??$cfg['chatId']??'';if(!preg_match('/^[0-9]{3,40}$/D',(string)$id))throw new RuntimeException('شناسهٔ عددی اکانت اینستاگرام لازم است.');$r=call_user_func($this->http,'https://graph.facebook.com/v22.0/'.$id.'?fields=id,username',['Authorization: Bearer '.$token]);if($r['status']!==200||empty($r['body']['id']))throw new RuntimeException('خواندن اکانت اینستاگرام تأیید نشد؛ دسترسی Meta را بررسی کنید.');$result['stages'][]=['stage'=>'account_read','success'=>true];}$result['note']='تست فقط خواندنی است؛ قابلیت ارسال پست/استوری و مجوز انتشار با این تست اثبات نمی‌شود.';}
            else throw new RuntimeException('این تست از مسیر اختصاصی همان اتصال اجرا می‌شود.');$result['success']=true;
        }catch(RuntimeException $e){$result['error']=$e->getMessage();}
        $result['elapsed_ms']=(int)round((microtime(true)-$start)*1000);$this->store->transaction(static function(&$s)use($project,$principal,$platform,$result){$stored=$result;$stored['_config_fingerprint']=self::fingerprint($project,$platform);$s['integration_tests'][$project['id']][$platform]=$stored;AiStore::audit($s,$principal,'connection_test',['platform'=>$platform,'success'=>$result['success']]);});return $result;
    }
    public function overview($project){$s=$this->store->read();$sources=(new AiHub($this->store))->sources($project);$rows=[];foreach($sources as $source){$rows[]=['source'=>$source['id'],'name'=>$source['name'],'enabled'=>$source['enabled'],'transport'=>$source['transport']??'manual','last_received'=>$source['last_received']??[],'last_complete'=>$source['last_complete']??[],'google_connected'=>$source['google_connected']??false,'note'=>'وجود تنظیمات یا دادهٔ قدیمی، موفقیت تست زنده نیست.'];}$tests=$s['integration_tests'][$project['id']]??[];foreach($tests as $platform=>&$test){$changed=($test['_config_fingerprint']??'')!==self::fingerprint($project,$platform);$expired=($test['checked_at']??0)<time()-86400;$test['stale']=$changed||$expired;if($test['stale']){$test['previous_success']=$test['success']??false;$test['success']=false;$test['note']=$changed?'تنظیمات تغییر کرده؛ تست اتصال را دوباره اجرا کنید.':'تست بیش از ۲۴ ساعت قبل انجام شده؛ دوباره تست کنید.';}unset($test['_config_fingerprint']);}unset($test);return ['profile'=>self::profile($project),'sources'=>$rows,'tests'=>$tests];}
}
